	@Test
	void findAllVariablesUsedInQueryPreservesValuesVariableOrder() {
		ParsedTupleQuery parsedQuery = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, """
				PREFIX social: <http://example.com/theme/social/>
				SELECT (COUNT(DISTINCT ?pair) AS ?count) WHERE {
				  VALUES (?u ?v) {
				    (<http://example.com/theme/social/user/0> <http://example.com/theme/social/user/0>)
				    (<http://example.com/theme/social/user/0> <http://example.com/theme/social/user/1>)
				  }
				  FILTER (?u != ?v)
				  ?u social:follows ?v .
				  OPTIONAL {
				    ?u social:name ?optName .
				  }
				  FILTER (?optName IN ("user0", "user1", "user2"))
				  BIND(CONCAT(STR(?u), STR(?v)) AS ?pair)
				}
				""", null);

		QueryRoot root = (QueryRoot) parsedQuery.getTupleExpr();
		BindingSetAssignment before = findFirst(root, BindingSetAssignment.class);
		assertEquals(List.of("u", "v"), new ArrayList<>(before.getBindingNames()));

		ArrayBindingBasedQueryEvaluationContext.findAllVariablesUsedInQuery(root);

		BindingSetAssignment after = findFirst(root, BindingSetAssignment.class);
		assertEquals(List.of("u", "v"), new ArrayList<>(after.getBindingNames()));
	}

	@Test
	void findAllVariablesUsedInQueryPreservesDeclaredUndefColumns() {
		ParsedTupleQuery parsedQuery = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, """
				SELECT * WHERE {
				  VALUES (?bound ?neverBound) { ("value" UNDEF) }
				}
				""", null);

		QueryRoot root = (QueryRoot) parsedQuery.getTupleExpr();
		BindingSetAssignment before = findFirst(root, BindingSetAssignment.class);
		assertEquals(List.of("bound", "neverBound"),
				new ArrayList<>(before.getDeclaredBindingNames()));

		ArrayBindingBasedQueryEvaluationContext.findAllVariablesUsedInQuery(root);

		BindingSetAssignment after = findFirst(root, BindingSetAssignment.class);
		assertEquals(List.of("bound", "neverBound"),
				new ArrayList<>(after.getDeclaredBindingNames()));
		assertEquals(List.of("bound"), new ArrayList<>(after.getPossibleBindingNames()));
	}

	@Test
	void failedExtensionDoesNotPoisonLaterStatementPatternInEitherBindingContext() throws Exception {
		ValueFactory valueFactory = SimpleValueFactory.getInstance();
		IRI subject = valueFactory.createIRI("urn:subject");
		IRI predicate = valueFactory.createIRI("urn:predicate");
		Value object = valueFactory.createLiteral("object");
		Statement statement = valueFactory.createStatement(subject, predicate, object);
		TripleSource tripleSource = new SingleStatementTripleSource(valueFactory, statement);
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(tripleSource, null);

		BindingSetAssignment seed = new BindingSetAssignment();
		MapBindingSet seedRow = new MapBindingSet();
		seedRow.addBinding("seed", valueFactory.createLiteral("row"));
		seed.setBindingSets(List.of(seedRow));
		Extension failedBind = new Extension(seed,
				new ExtensionElem(Var.of("unbound"), "subject"));
		StatementPattern followingPattern = new StatementPattern(Var.of("subject"), Var.of("predicate"),
				Var.of("object"));
		QueryRoot query = new QueryRoot(new Join(failedBind, followingPattern));
		QueryEvaluationContext.Minimal minimal = new QueryEvaluationContext.Minimal((Dataset) null, valueFactory, null);

		List<BindingSet> ordinaryResults = evaluate(strategy.precompile(query.clone(), minimal));
		ArrayBindingBasedQueryEvaluationContext arrayContext = new ArrayBindingBasedQueryEvaluationContext(minimal,
				ArrayBindingBasedQueryEvaluationContext.findAllVariablesUsedInQuery(query),
				tripleSource.getComparator());
		List<BindingSet> arrayResults = evaluate(strategy.precompile(query.clone(), arrayContext));

		assertThat(arrayResults).hasSize(1);
		assertThat(ordinaryResults).hasSize(1);
		for (BindingSet result : List.of(ordinaryResults.getFirst(), arrayResults.getFirst())) {
			assertThat(result.getValue("subject")).isEqualTo(subject);
			assertThat(result.getValue("predicate")).isEqualTo(predicate);
			assertThat(result.getValue("object")).isEqualTo(object);
			assertThat(result.getValue("seed")).isEqualTo(valueFactory.createLiteral("row"));
		}
	}

	@Test
	void failedExtensionClearsAnExistingTargetAcrossBindingSetImplementations() throws Exception {
		ValueFactory valueFactory = SimpleValueFactory.getInstance();
		BindingSetAssignment seed = new BindingSetAssignment();
		MapBindingSet seedRow = new MapBindingSet();
		seedRow.addBinding("seed", valueFactory.createLiteral("row"));
		seedRow.addBinding("target", valueFactory.createIRI("urn:old-target"));
		seed.setBindingSets(List.of(seedRow));

		QueryRoot query = new QueryRoot(new Extension(seed,
				new ExtensionElem(Var.of("missing"), "target")));
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		List<QueryEvaluationContext> contexts = bindingContexts(query, valueFactory);

		assertAll(contexts.stream().map(context -> (Executable) () -> {
			List<BindingSet> results = evaluate(strategy.precompile(query.clone(), context));
			assertThat(results).hasSize(1);
			assertOnlySeedBinding(results.getFirst());
			assertThat(results.getFirst().getValue("seed")).isEqualTo(valueFactory.createLiteral("row"));
		}).toArray(Executable[]::new));
	}

	@Test
	void expressionErrorClearsTargetAndInvalidatesBindingSetViews() throws Exception {
		ValueFactory valueFactory = SimpleValueFactory.getInstance();
		BindingSetAssignment seed = seedAssignment(valueFactory);
		ValueExpr expression = new ValueConstant(valueFactory.createLiteral("unused"));
		Extension extension = new Extension(seed, new ExtensionElem(expression, "target"));
		QueryRoot query = new QueryRoot(extension);
		MapBindingSet seedRow = seedRow(valueFactory);
		List<QueryEvaluationContext> contexts = bindingContexts(query, valueFactory);

		assertAll(contexts.stream().map(context -> (Executable) () -> {
			QueryValueEvaluationStep failingStep = bindings -> {
				assertThat(bindings.getBindingNames()).contains("target");
				if (bindings instanceof ArrayBindingSet arrayBindingSet) {
					assertThat(arrayBindingSet.getSortedBindingNames()).contains("target");
				}
				throw new ValueExprEvaluationException("expected expression failure");
			};
			EvaluationStrategy strategy = mock(EvaluationStrategy.class);
			doReturn(failingStep).when(strategy).precompile(eq(expression), eq(context));
			MutableBindingSet bindings = context.createBindingSet(seedRow);
			ExtensionIterator.buildLambdaToEvaluateTheExpressions(extension, strategy, context).accept(bindings);
			assertOnlySeedBinding(bindings);
		}).toArray(Executable[]::new));
	}

	@Test
	void failedExtensionIsVisibleToFollowingBoundCoalesceAndExtensionElements() throws Exception {
		ValueFactory valueFactory = SimpleValueFactory.getInstance();
		Literal fallback = valueFactory.createLiteral("fallback");
		BindingSetAssignment seed = seedAssignment(valueFactory);
		Extension extension = new Extension(seed,
				new ExtensionElem(Var.of("missing"), "target"),
				new ExtensionElem(new Bound(Var.of("target")), "wasBound"),
				new ExtensionElem(new Coalesce(List.of(Var.of("target"), new ValueConstant(fallback))), "coalesced"),
				new ExtensionElem(Var.of("target"), "copy"));
		QueryRoot query = new QueryRoot(extension);
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		List<QueryEvaluationContext> contexts = bindingContexts(query, valueFactory);

		assertAll(contexts.stream().map(context -> (Executable) () -> {
			List<BindingSet> results = evaluate(strategy.precompile(query.clone(), context));
			assertThat(results).hasSize(1);
			BindingSet result = results.getFirst();
			assertTargetAbsent(result);
			assertThat(result.getValue("wasBound")).isEqualTo(valueFactory.createLiteral(false));
			assertThat(result.getValue("coalesced")).isEqualTo(fallback);
			assertThat(result.hasBinding("copy")).isFalse();
		}).toArray(Executable[]::new));
	}

